import { Globe } from 'lucide-react';
import { handle, API_BASE } from '../lib/api';
import { usePanelData } from '../hooks/usePanelData';
import type {
  PeersResponse,
  PeerAgencySummary,
  PeerRecoveryPoint,
  MiwayAnnualPoint,
} from '../types';
import { fmtInt } from '../lib/format';
import { EmptyState, PanelSkeleton } from './PanelStates';

/**
 * Peers & open data: the app's analysis running on TransLink's published
 * stop-level ridership, side by side with what exists for MiWay.
 *
 * This is the working proof behind the PRESTO data request: every number on
 * the TransLink side comes from a dataset TransLink publishes under an open
 * licence with no request at all — the same data class the request asks
 * MiWay for. The MiWay side shows what this project had to build by hand
 * (the collector) or estimate (calibrated boardings) because the data is
 * not published.
 *
 * Nothing here is modeled: TransLink rows are its published APC aggregates,
 * MiWay rows are its published figures plus this project's own observations.
 */

function pct(x: number | undefined): string {
  return x == null ? '—' : `${Math.round(x * 100)}%`;
}

function StatBlock({
  label,
  value,
  sub,
  tone,
}: {
  label: string;
  value: string;
  sub?: string;
  tone?: 'green' | 'amber' | 'danger';
}) {
  const toneCls =
    tone === 'green'
      ? 'text-optimized'
      : tone === 'amber'
        ? 'text-bottleneck'
        : tone === 'danger'
          ? 'text-danger'
          : 'text-text-primary';
  return (
    <div className="rounded-xl border border-border bg-card-hover/40 p-3">
      <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">
        {label}
      </div>
      <div className={`mt-1 text-lg font-bold tabular-nums ${toneCls}`}>{value}</div>
      {sub ? <div className="mt-0.5 text-[10px] text-text-muted">{sub}</div> : null}
    </div>
  );
}

function RecoveryTrend({
  trend,
}: {
  trend: PeerRecoveryPoint[];
}) {
  const max = Math.max(...trend.map((p) => p.weekday_boardings), 1);
  return (
    <div className="border-t border-border p-4">
      <div className="flex items-baseline justify-between">
        <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">
          Post-pandemic recovery — weekday boardings, all published years
        </div>
        <div className="text-[10px] font-semibold text-text-muted">
          % of 2019 baseline
        </div>
      </div>
      <div className="mt-3 flex items-end gap-3">
        {trend.map((p) => {
          const h = Math.max(6, Math.round((p.weekday_boardings / max) * 72));
          const recovered = p.pct_of_2019 >= 100;
          return (
            <div key={p.year} className="flex flex-1 flex-col items-center gap-1">
              <div className="text-[11px] font-bold tabular-nums text-text-primary">
                {fmtInt(p.weekday_boardings)}
              </div>
              <div
                className={`w-full rounded-t-md ${
                  recovered ? 'bg-optimized' : 'bg-bottleneck'
                }`}
                style={{ height: `${h}px` }}
                title={`${p.year}: ${fmtInt(p.weekday_boardings)} weekday boardings (${p.pct_of_2019}% of 2019)`}
              />
              <div className="text-[11px] font-semibold text-text-secondary">
                {p.year}
              </div>
              <div
                className={`text-[10px] font-bold tabular-nums ${
                  recovered ? 'text-optimized' : 'text-bottleneck'
                }`}
              >
                {p.pct_of_2019}%
              </div>
            </div>
          );
        })}
      </div>
      <div className="mt-2 text-[10px] leading-relaxed text-text-muted">
        Four years of published APC data — a trend nobody can build for MiWay
        from a single October figure. Bars stay amber until demand returns to
        the 2019 baseline. Network composition changes between TSPR editions
        (2019 predates the 2021 redesign), so treat year-over-year deltas as
        directional.
      </div>
    </div>
  );
}

function MiwayAnnualTrend({
  series,
}: {
  series: MiwayAnnualPoint[];
}) {
  const barSeries = series.filter((p) => p.boardings_millions != null);
  const annotations = series.filter((p) => p.boardings_millions == null && p.is_annotation);
  const max = Math.max(
    ...barSeries.map((p) => p.boardings_millions ?? 0),
    1,
  );
  return (
    <div className="border-t border-border p-4">
      <div className="flex items-baseline justify-between">
        <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">
          MiWay annual boardings — as published, gaps included
        </div>
        <div className="text-[10px] font-semibold text-text-muted">millions</div>
      </div>
      <div className="mt-3 flex items-end gap-3">
        {barSeries.map((p) => {
          if (p.boardings_millions == null) {
            return (
              <div
                key={p.year}
                className="flex flex-1 flex-col items-center gap-1"
              >
                <div className="flex h-[72px] items-center text-[10px] text-text-muted">
                  never published
                </div>
                <div className="w-full rounded-t-md border border-dashed border-border bg-card-hover/30" style={{ height: '6px' }} />
                <div className="text-[11px] font-semibold text-text-secondary">
                  {p.year}
                </div>
                <div className="h-4" />
              </div>
          );
          }
          const h = Math.max(6, Math.round(((p.boardings_millions ?? 0) / max) * 72));
          return (
            <div key={p.year} className="flex flex-1 flex-col items-center gap-1">
              <div className="text-[11px] font-bold tabular-nums text-text-primary">
                {p.boardings_millions}M
              </div>
              <div
                className="w-full rounded-t-md bg-accent/70"
                style={{ height: `${h}px` }}
                title={`${p.year}: ${p.boardings_millions}M ${p.metric} — ${p.source}`}
              />
              <div className="text-[11px] font-semibold text-text-secondary">
                {p.year}
              </div>
              <div className="h-4 text-center text-[9px] leading-tight text-text-muted">
                {p.metric}
              </div>
            </div>
          );
        })}
      </div>
      {annotations.length > 0 && (
        <div className="mt-2 space-y-1">
          {annotations.map((p) => (
            <div
              key={p.year}
              className="text-[10px] leading-relaxed text-text-muted"
              title={p.source}
            >
              <span className="font-semibold text-text-secondary">{p.metric}</span>{' '}
              — newest weekday figure in print, published in an academic study
              (U of T, 2025) rather than a City document.
            </div>
          ))}
        </div>
      )}
      <div className="mt-2 text-[10px] leading-relaxed text-text-muted">
        2019 was never published as an annual figure, and the metric shifts
        between documents (boardings vs revenue ridership) — so the curve has a
        hole where its baseline should be and bars that are not strictly
        comparable. TransLink's equivalent chart is one table with fixed
        definitions. This section shows both curves exactly as published;
        nothing is imputed.
      </div>
    </div>
  );
}

/**
 * Tri-agency recovery on one scale: 2019 = 100 for all three.
 *
 * MiWay's points come from the FAO/CUTA-linked baseline (the payload's
 * miway_recovery_index — the join is documented and CI-checked); the
 * as-published series with its 2019 hole stays visible in the MiWay card
 * below. TransLink uses its published pct-of-2019; TTC uses the Munro-derived
 * Fall route-sum index. Dashed line = the 2019 baseline.
 */
const SCALE_MAX = 110;

function CommonScaleRecovery({
  series,
}: {
  series: { name: string; colorCls: string; points: { year: number; index: number }[] }[];
}) {
  const years = Array.from(
    new Set(series.flatMap((s) => s.points.map((p) => p.year))),
  ).sort((a, b) => a - b);
  const idxOf = (name: string, y: number) =>
    series.find((s) => s.name === name)?.points.find((p) => p.year === y)?.index;
  const h = (idx: number) => Math.max(4, Math.round((idx / SCALE_MAX) * 80));
  return (
    <div className="border-t border-border p-4">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">
          Recovery on a common scale — 2019 = 100
        </div>
        <div className="flex items-center gap-3">
          {series.map((s) => (
            <span key={s.name} className="flex items-center gap-1 text-[10px] text-text-secondary">
              <span className={`inline-block h-2 w-2 rounded-sm ${s.colorCls}`} />
              {s.name}
            </span>
          ))}
        </div>
      </div>
      <div className="relative mt-3">
        <div
          className="absolute left-0 right-0 border-t border-dashed border-text-muted/50"
          style={{ bottom: `${h(100)}px` }}
          title="2019 baseline = 100"
        />
        <div className="flex items-end gap-2">
          {years.map((y) => (
            <div key={y} className="flex flex-1 flex-col items-center">
              <div className="flex h-[80px] w-full items-end justify-center gap-[3px]">
                {series.map((s) => {
                  const idx = idxOf(s.name, y);
                  if (idx == null) return null;
                  return (
                    <div
                      key={s.name}
                      className={`w-3 rounded-t-sm ${s.colorCls}`}
                      style={{ height: `${h(idx)}px` }}
                      title={`${s.name} ${y}: ${idx} (2019=100)`}
                    />
                  );
                })}
              </div>
              <div className="mt-1 text-[10px] font-semibold text-text-secondary">{y}</div>
            </div>
          ))}
        </div>
      </div>
      <div className="mt-2 text-[10px] leading-relaxed text-text-muted">
        Hover bars for exact indices. MiWay's 2019 baseline is the FAO/CUTA
        linked-trip figure (41.2M) joined to its published boardings at the
        2022 overlap — a derivation MiWay itself never published. TTC points
        are Fall route-sums from the Munro compilation; TransLink points are
        its published pct-of-2019. Same scale, three documentation burdens.
      </div>
    </div>
  );
}

/**
 * Service-supply recovery — what happened to the hours behind the ridership
 * curves. MiWay's row carries its own published daily hours; the peers'
 * rows quote their printed recovery figures. Ridership ÷ these hours is
 * the crowding story.
 */
function ServiceSupply({
  supply,
}: {
  supply: NonNullable<PeersResponse['service_supply']>;
}) {
  return (
    <div className="border-t border-border p-4">
      <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">
        Service supply since 2019 — the denominator behind the recovery curves
      </div>
      <div className="mt-2 space-y-1.5">
        {supply.rows.map((r) => {
          const down = (r.pct_change ?? 0) < 0;
          return (
            <div
              key={r.agency}
              className="flex items-baseline justify-between gap-3 border-t border-border py-1.5 first:border-t-0"
            >
              <div className="min-w-0">
                <div className="text-xs font-semibold text-text-primary">{r.agency}</div>
                <div className="text-[10px] leading-tight text-text-muted">
                  {r.metric}
                  {r.value_then != null && r.value_now != null
                    ? ` — ${fmtInt(r.value_then)} → ${fmtInt(r.value_now)}`
                    : ''}
                </div>
                <div className="text-[10px] leading-tight text-text-muted">{r.context}</div>
              </div>
              <div
                className={`shrink-0 text-sm font-bold tabular-nums ${
                  r.pct_change == null
                    ? 'text-text-muted'
                    : down
                      ? 'text-danger'
                      : 'text-optimized'
                }`}
                title={r.value_then != null && r.value_now != null
                  ? `${fmtInt(r.value_then)} (${r.year_then}) → ${fmtInt(r.value_now)} (${r.year_now})`
                  : undefined}
              >
                {r.pct_change == null
                  ? 'grew'
                  : `${r.pct_change > 0 ? '+' : ''}${r.pct_change}%`}
              </div>
            </div>
          );
        })}
      </div>
      <div className="mt-2 text-[10px] leading-relaxed text-text-muted">{supply.note}</div>
    </div>
  );
}

/** Ontario-wide context from the FAO table: every major agency, one basis. */
function OntarioContext({
  ctx,
}: {
  ctx: NonNullable<PeersResponse['ontario_context']>;
}) {
  const rows = [...ctx.rows].sort(
    (a, b) => (b.trips_millions[2022] ?? 0) - (a.trips_millions[2022] ?? 0),
  );
  return (
    <div className="border-t border-border p-4">
      <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">
        Ontario recovery context — annual linked trips, millions (FAO/CUTA)
      </div>
      <table className="mt-2 w-full text-xs">
        <thead>
          <tr className="text-left text-[10px] uppercase tracking-wider text-text-muted">
            <th className="py-1 font-bold">Agency</th>
            <th className="py-1 text-right font-bold">2019</th>
            <th className="py-1 text-right font-bold">2022</th>
            <th className="py-1 text-right font-bold">% of 2019</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => {
            const y19 = r.trips_millions[2019];
            const y22 = r.trips_millions[2022];
            const pct19 = y19 && y22 ? Math.round((y22 / y19) * 100) : null;
            const isMiway = r.agency.includes('MiWay');
            return (
              <tr
                key={r.agency}
                className={`border-t border-border ${isMiway ? 'bg-accent/10 font-semibold' : ''}`}
              >
                <td className="py-1 pr-2 text-text-primary">{r.agency}</td>
                <td className="py-1 text-right tabular-nums text-text-secondary">
                  {y19 ?? '—'}
                </td>
                <td className="py-1 text-right tabular-nums text-text-secondary">
                  {y22 ?? '—'}
                </td>
                <td
                  className={`py-1 text-right tabular-nums ${
                    pct19 != null && pct19 >= 90 ? 'text-optimized' : 'text-bottleneck'
                  }`}
                >
                  {pct19 != null ? `${pct19}%` : '—'}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <div className="mt-2 text-[10px] leading-relaxed text-text-muted">
        One methodology, every major Ontario agency — the comparison MiWay's
        own publications cannot support for itself. Brampton (98%) vs MiWay
        (87%) is the same region, same pandemic, same years: the difference
        is demand, not “transit is recovering”. MiWay's 2019 figure exists
        here only because CUTA publishes what the agency itself does not.
      </div>
    </div>
  );
}

function AgencyHeader({ a }: { a: PeerAgencySummary }) {
  return (
    <div className="flex items-center gap-2.5 border-b border-border px-5 py-3">
      <span className="rounded-lg bg-accent/15 p-1.5">
        <Globe className="h-4 w-4 text-accent" />
      </span>
      <div>
        <h3 className="text-sm font-bold text-text-primary">{a.agency}</h3>
        <div className="text-[10px] text-text-muted">
          {a.source} · {a.period}
        </div>
      </div>
      <span
        className={`ml-auto rounded-full border px-2 py-0.5 text-[9px] font-semibold ${
          a.published_stop_level
            ? 'border-optimized/30 bg-optimized/10 text-optimized'
            : 'border-danger/30 bg-danger/10 text-danger'
        }`}
      >
        {a.published_stop_level ? 'published stop-level' : 'not published'}
      </span>
    </div>
  );
}

export default function PeersPanel() {
  // P2: fetch/loading/error owned by the hook. This panel bypasses the api
  // singleton (raw fetch + handle, the same as before) inside the fetcher —
  // the hook doesn't care where the promise comes from.
  const { data, error } = usePanelData<PeersResponse>({
    fetcher: (signal) =>
      fetch(`${API_BASE}/peers`, { signal }).then((r) => handle<PeersResponse>(r)),
  });

  if (error)
    return (
      <EmptyState
        title="Peer comparison unavailable"
        hint={error}
      />
    );
  if (!data) return <PanelSkeleton label="Loading peer open-data comparison…" />;

  const t = data.translink;
  const m = data.miway;

  return (
    <div className="flex-1 overflow-y-auto">
      <div className="mx-auto max-w-3xl space-y-3 p-2">
        {/* the headline contrast */}
        <section className="rounded-2xl border border-border bg-card p-5">
          <div className="flex items-center gap-2.5">
            <span className="rounded-lg bg-accent/15 p-1.5">
              <Globe className="h-4 w-4 text-accent" />
            </span>
            <h2 className="text-base font-bold text-text-primary">
              The same analysis, two agencies, one missing dataset
            </h2>
          </div>
          <p className="mt-2 text-xs leading-relaxed text-text-secondary">
            Every TransLink number below comes from a stop-level ridership
            dataset TransLink publishes openly — no request, no agreement. The
            MiWay column shows what had to be built by hand or estimated
            because the equivalent dataset is not published here. This panel
            is the working demo attached to the PRESTO data request.
          </p>
        </section>

        {t ? (
          <>
            {/* TransLink card */}
            <section className="overflow-hidden rounded-2xl border border-border bg-card">
              <AgencyHeader a={t} />
              <div className="grid grid-cols-2 gap-2.5 p-4 sm:grid-cols-4">
                <StatBlock
                  label="Weekday boardings"
                  value={fmtInt(t.total_boardings)}
                  sub={`${t.routes} lines, all published APC`}
                />
                <StatBlock
                  label="Stops with data"
                  value={fmtInt(t.stops_measured ?? 0)}
                  sub="every stop, published"
                />
                <StatBlock
                  label="Top 10% of stops"
                  value={pct(t.top10_stop_share)}
                  sub="share of all boardings"
                  tone="amber"
                />
                <StatBlock
                  label="Boardings per journey"
                  value={
                    t.journey_stats?.boardings_per_journey != null
                      ? t.journey_stats.boardings_per_journey.toFixed(2)
                      : '—'
                  }
                  sub="401.8M boardings / 240.9M journeys, both published"
                  tone="green"
                />
              </div>
              <div className="grid gap-0 border-t border-border sm:grid-cols-2">
                <div className="border-b border-border p-4 sm:border-b-0 sm:border-r">
                  <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">
                    Busiest lines (weekday boardings)
                  </div>
                  <ul className="mt-2 space-y-1.5 text-xs">
                    {t.top_lines?.map((l) => (
                      <li key={l.route} className="flex justify-between gap-2">
                        <span className="font-semibold text-text-primary">
                          Line {l.route}
                        </span>
                        <span className="tabular-nums text-text-secondary">
                          {fmtInt(l.boardings)}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>
                <div className="p-4">
                  <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">
                    Busiest stops (weekday boardings)
                  </div>
                  <ul className="mt-2 space-y-1.5 text-xs">
                    {t.busiest_stops?.map((s) => (
                      <li key={s.stop_id} className="flex justify-between gap-2">
                        <span className="truncate font-semibold text-text-primary">
                          {s.stop_name}
                        </span>
                        <span className="shrink-0 tabular-nums text-text-secondary">
                          {fmtInt(s.boardings)}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
              <div className="border-t border-border px-4 py-2 text-[10px] text-text-muted">
                Transfer-demand share computed from published stop × line data —
                a co-location proxy. The PRESTO request asks for the observed
                version of this same table.
              </div>
              {t.recovery_trend && t.recovery_trend.length >= 2 ? (
                <RecoveryTrend trend={t.recovery_trend} />
              ) : null}
            </section>

            {/* MiWay card */}
            <section className="overflow-hidden rounded-2xl border border-border bg-card">
              <AgencyHeader a={m} />
              <div className="grid grid-cols-2 gap-2.5 p-4 sm:grid-cols-4">
                <StatBlock
                  label="Weekday boardings"
                  value={fmtInt(m.total_boardings)}
                  sub={`${m.routes_published} published / ${m.routes_estimated} estimated`}
                  tone="amber"
                />
                <StatBlock
                  label="Stops with published data"
                  value="0"
                  sub="not published by the agency"
                  tone="danger"
                />
                <StatBlock
                  label="Top 10% of stops"
                  value="—"
                  sub="unknowable without the data"
                  tone="danger"
                />
                <StatBlock
                  label="Boardings per journey"
                  value="—"
                  sub="journeys never published — and provably not derivable from vehicle data"
                  tone="danger"
                />
              </div>
              <div className="border-t border-border px-4 py-2 text-[10px] leading-relaxed text-text-muted">
                TransLink computes 1.67 boardings per journey (2024) because its
                fare data links boardings into journeys. No vehicle-side sensor
                — MiWay's APCs or this project's collector — can make that link:
                a transfer is two unlinked boarding events on different buses.
                Only tap-level fare data can measure it. This is the PRESTO ask.
              </div>
              <div className="border-t border-border px-4 py-2 text-[10px] leading-relaxed text-text-muted">
                Stop-level insight exists only because this project built a
                GTFS-RT collector and ran it for weeks. TransLink makes the
                equivalent table a one-click download. The 2019 baseline this
                card's curve lacks below comes from CUTA data via the FAO —
                see the common-scale chart and Ontario table underneath.
              </div>
              {data.miway_annual_series &&
              data.miway_annual_series.length >= 2 ? (
                <MiwayAnnualTrend series={data.miway_annual_series} />
              ) : null}
            </section>

            {/* Common-scale recovery: 2019 = 100, all three agencies */}
            {data.translink?.recovery_trend &&
            data.miway_recovery_index &&
            data.ttc_surface_fall_index ? (
              <section className="overflow-hidden rounded-2xl border border-border bg-card">
                <CommonScaleRecovery
                  series={[
                    {
                      name: 'TransLink bus',
                      colorCls: 'bg-optimized',
                      points: data.translink.recovery_trend.map((p) => ({
                        year: p.year,
                        index: p.pct_of_2019,
                      })),
                    },
                    {
                      name: 'TTC surface',
                      colorCls: 'bg-bottleneck',
                      points: data.ttc_surface_fall_index.points.map((p) => ({
                        year: p.year,
                        index: p.index_2019,
                      })),
                    },
                    {
                      name: 'MiWay',
                      colorCls: 'bg-accent',
                      points: data.miway_recovery_index.points.map((p) => ({
                        year: p.year,
                        index: p.index_2019,
                      })),
                    },
                  ]}
                />
              </section>
            ) : null}

            {/* Service-supply denominator */}
            {data.service_supply ? (
              <section className="overflow-hidden rounded-2xl border border-border bg-card">
                <ServiceSupply supply={data.service_supply} />
              </section>
            ) : null}

            {/* Ontario-wide context (FAO/CUTA) */}
            {data.ontario_context ? (
              <section className="overflow-hidden rounded-2xl border border-border bg-card">
                <OntarioContext ctx={data.ontario_context} />
              </section>
            ) : null}
          </>
        ) : (
          <section className="overflow-hidden rounded-2xl border border-border bg-card">
            <AgencyHeader a={m} />
            <div className="p-4">
              <EmptyState
                title="TransLink demo datasets not found"
                hint="Run scripts/build_translink_demo.py to generate the peer comparison."
              />
            </div>
          </section>
        )}

        <section className="rounded-2xl border border-border bg-card p-5">
          <p className="text-[11px] leading-relaxed text-text-muted">{data.note}</p>
          {data.trend_note ? (
            <p className="mt-2 text-[11px] leading-relaxed text-text-muted">
              {data.trend_note}
            </p>
          ) : null}
          <p className="mt-2 text-[11px] leading-relaxed text-text-muted">
            Vancouver is not Mississauga — SkyTrain trunk corridors concentrate
            demand differently than an all-bus network. This comparison shows
            what the analysis looks like when the data exists; it is not a
            claim that one network is better than the other.
          </p>
        </section>
      </div>
    </div>
  );
}
